import{_ as e,o as c,c as o,a4 as a}from"./chunks/framework.vNSRaLQv.js";const u=JSON.parse('{"title":"ccswitch \\"应用 &lt;agent&gt; 配置\\" 写入策略是\\"整段追加\\",导致 YAML duplicate 键报错","description":"","frontmatter":{"title":"ccswitch \\"应用 &lt;agent&gt; 配置\\" 写入策略是\\"整段追加\\",导致 YAML duplicate 键报错","date":"2026-06-07T00:00:00.000Z"},"headers":[],"relativePath":"posts/hermes-ccswitch-config-bug-复盘.md","filePath":"posts/hermes-ccswitch-config-bug-复盘.md"}'),d={name:"posts/hermes-ccswitch-config-bug-复盘.md"};function i(l,t,s,p,r,n){return c(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="ccswitch-应用-lt-agent-gt-配置-写入策略是-整段追加-导致-yaml-duplicate-键报错" tabindex="-1">ccswitch &quot;应用 &lt;agent&gt; 配置&quot; 写入策略是&quot;整段追加&quot;,导致 YAML duplicate 键报错 <a class="header-anchor" href="#ccswitch-应用-lt-agent-gt-配置-写入策略是-整段追加-导致-yaml-duplicate-键报错" aria-label="Permalink to &quot;ccswitch &quot;应用 &amp;lt;agent&amp;gt; 配置&quot; 写入策略是&quot;整段追加&quot;,导致 YAML duplicate 键报错&quot;">​</a></h1><blockquote><p>一份给 ccswitch 维护者的 issue 草稿。适用于任何被 ccswitch 管理的、配置文件是 YAML 格式的 agent / runtime(claude / codex / gemini 之外的第三方应用,例如 hermes / openclaw 等)。</p></blockquote><hr><h2 id="环境" tabindex="-1">环境 <a class="header-anchor" href="#环境" aria-label="Permalink to &quot;环境&quot;">​</a></h2><ul><li>ccswitch (Rust 编译的 Tauri 桌面应用,托盘常驻)</li><li>任意受 ccswitch 管理的第三方 agent / runtime(下文以 <code>&amp;lt;agent&amp;gt;</code> 代替)</li><li>配置文件: <code>~/{app 配置目录}/config.yaml</code></li><li>操作系统: Windows 11(在 macOS / Linux 应同样可复现,因为问题在 ccswitch 的 Rust 代码,不在 OS 行为)</li></ul><h2 id="现象" tabindex="-1">现象 <a class="header-anchor" href="#现象" aria-label="Permalink to &quot;现象&quot;">​</a></h2><p>启动 <code>&amp;lt;agent&amp;gt;</code> 时报:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>配置错误: Failed to parse &amp;lt;agent&amp;gt; config as YAML: duplicate entry with key &quot;...&quot;</span></span></code></pre></div><p><code>...</code> 可能是 <code>custom_providers</code> / <code>model</code> / <code>mcp_servers</code> 三者之一,也可能其他顶层键。</p><p><code>config.yaml</code> 里出现重复的顶层键。</p><h2 id="复现步骤" tabindex="-1">复现步骤 <a class="header-anchor" href="#复现步骤" aria-label="Permalink to &quot;复现步骤&quot;">​</a></h2><ol><li>正常使用 <code>&amp;lt;agent&amp;gt;</code>,<code>config.yaml</code> 是 <code>&amp;lt;agent&amp;gt;</code> 自己的完整配置(包含 agent / terminal / display / voice / security / cron / kanban / gateway / 各种 auxiliary provider 等数百个字段)</li><li>在 ccswitch 托盘菜单里点击 <code>&amp;lt;agent&amp;gt;</code> 的&quot;切换到 &lt;某个供应商&gt;&quot;(或 ccswitch 自动检测到 model 指针指向不存在的供应商,自动重建)</li><li>触发&quot;应用 &lt;agent&gt;&quot; 动作</li><li>再次启动 <code>&amp;lt;agent&amp;gt;</code> → YAML 报 duplicate</li></ol><h2 id="根因" tabindex="-1">根因 <a class="header-anchor" href="#根因" aria-label="Permalink to &quot;根因&quot;">​</a></h2><p>ccswitch 的 &quot;update &lt;agent&gt; model defaults after switching to &#39;&lt;provider&gt;&#39;&quot; 函数(疑似位于 <code>cc_switch_lib::services::provider</code> 模块)实现是:</p><blockquote><p>从 ccswitch 自己的数据库(<code>cc-switch.db</code> 的 <code>providers</code> 表)读出&quot;它认为完整的 <code>&amp;lt;agent&amp;gt;</code> 配置&quot; → <strong>整段附加到 <code>&amp;lt;agent&amp;gt;</code> 的 <code>config.yaml</code> 末尾</strong></p></blockquote><p>这份&quot;完整配置&quot;至少包含三个顶层键:</p><ul><li><code>model:</code> (当前激活的 default + provider)</li><li><code>custom_providers:</code> (所有 <code>&amp;lt;agent&amp;gt;</code> 供应商列表)</li><li><code>mcp_servers:</code> (ccswitch 还会顺便带一份 mcp server 配置)</li></ul><p><strong>ccswitch 从来不做 in-place 合并,只会&quot;追加整段&quot;</strong>。所以:</p><table tabindex="0"><thead><tr><th>情况</th><th>结果</th></tr></thead><tbody><tr><td>目标文件已有 <code>model:</code> 块</td><td>追加后 → duplicate <code>model</code></td></tr><tr><td>目标文件已有 <code>custom_providers</code> 段</td><td>追加后 → duplicate <code>custom_providers</code></td></tr><tr><td>目标文件已有 <code>mcp_servers</code> 段</td><td>追加后 → duplicate <code>mcp_servers</code></td></tr><tr><td>目标文件<strong>没有</strong>这些键</td><td>看起来&quot;成功&quot;,但 ccswitch 自己的小文件覆盖了 <code>&amp;lt;agent&amp;gt;</code> 的完整配置</td></tr></tbody></table><h2 id="旁证-ccswitch-对-lt-agent-gt-是-半吊子-管理" tabindex="-1">旁证:ccswitch 对 <code>&amp;lt;agent&amp;gt;</code> 是&quot;半吊子&quot;管理 <a class="header-anchor" href="#旁证-ccswitch-对-lt-agent-gt-是-半吊子-管理" aria-label="Permalink to &quot;旁证:ccswitch 对 `&amp;lt;agent&amp;gt;` 是&quot;半吊子&quot;管理&quot;">​</a></h2><p>(以一个第三方 agent 为例,以下是通用现象)</p><ul><li><code>cc-switch.db</code> 的 <code>proxy_config</code> 表有 claude / codex / gemini 的代理配置,<strong>不一定有 <code>&amp;lt;agent&amp;gt;</code></strong></li><li><code>proxy_live_backup</code> 表只对 claude / codex 有备份,<strong>不一定有 <code>&amp;lt;agent&amp;gt;</code></strong></li><li>ccswitch 日志里大量 <code>[Claude]</code> 和 <code>[Codex]</code> 的请求记录,<strong>很少或没有 <code>[&amp;lt;Agent&amp;gt;]</code></strong></li><li><code>settings.json</code> 里 <code>currentProvider&amp;lt;Agent&amp;gt;</code> 字段可能缺失</li><li><code>providers</code> 表里 <code>&amp;lt;agent&amp;gt;</code> 供应商的 <code>is_current</code> 字段长期为 0</li></ul><p>也就是说 ccswitch 在 UI 上声称管理 <code>&amp;lt;agent&amp;gt;</code>,但实现上<strong>不一定有装网络代理、不一定标 <code>is_current</code>、不一定有 live takeover 机制</strong>,而 &quot;update &lt;agent&gt; model defaults&quot; 函数又用了粗暴的&quot;追加&quot;策略。</p><h2 id="日志特征-对排查有用" tabindex="-1">日志特征(对排查有用) <a class="header-anchor" href="#日志特征-对排查有用" aria-label="Permalink to &quot;日志特征(对排查有用)&quot;">​</a></h2><ul><li>写入时<strong>不写 INFO 日志</strong>,只在失败时打 WARN,例如:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>[WARN][cc_switch_lib::services::provider]</span></span>\n<span class="line"><span>Failed to update &amp;lt;agent&amp;gt; model defaults after switching to &#39;&amp;lt;provider&amp;gt;&#39;:</span></span>\n<span class="line"><span>配置错误: Failed to parse &amp;lt;agent&amp;gt; config as YAML: duplicate entry with key &quot;custom_providers&quot;</span></span></code></pre></div></li><li>写入&quot;成功&quot;时<strong>完全静默</strong>,无任何日志输出</li><li>ccswitch 每次&quot;应用&quot;动作会在 <code>~/.cc-switch/backups/&amp;lt;app_type&amp;gt;/</code> 创建一份 <code>&amp;lt;app_type&amp;gt;_&amp;lt;时间戳&amp;gt;.yaml</code> 时间戳备份</li></ul><h2 id="建议的修复方向" tabindex="-1">建议的修复方向 <a class="header-anchor" href="#建议的修复方向" aria-label="Permalink to &quot;建议的修复方向&quot;">​</a></h2><p>按&quot;根治性&quot;递减,任选其一即可:</p><ol><li><strong>改 in-place 合并</strong>:读取文件 → 解析 YAML → 改 model 块的 default / provider 字段 → 写回。<strong>不要追加</strong>。</li><li><strong>写入前做 YAML 解析校验</strong>:用 <code>serde_yaml</code> / <code>yaml-rust</code> 解析写入后的文件,确保无重复键、无 schema 错误。失败就回滚 + 报错。</li><li><strong>写入前用锁文件机制</strong>:例如 <code>~/.{app}/.cc-switch.lock</code>,避免和 <code>&amp;lt;agent&amp;gt;</code> 自己的写入并发。</li><li><strong>如果决定保留&quot;整体重写&quot;策略</strong>: <ul><li>完整重写 <code>&amp;lt;agent&amp;gt;</code> config(不是追加),保留 <code>&amp;lt;agent&amp;gt;</code> 自己的所有字段(不光是 ccswitch 知道的 N 个供应商)</li><li>在重写前<strong>备份</strong>用户原始完整配置(不只备份 ccswitch 写的&quot;应用前&quot;版本)</li></ul></li><li><strong>如果决定保留&quot;追加&quot;策略</strong>(最不推荐): <ul><li>至少做去重:写入前先去掉 <code>model</code> / <code>custom_providers</code> / <code>mcp_servers</code> 这几个顶层键的旧值,再追加</li></ul></li><li><strong>降低日志噪音</strong>:写入&quot;成功&quot;也写一条 INFO,方便用户 / 开发者知道 ccswitch 对 <code>&amp;lt;agent&amp;gt;</code> 做了什么</li></ol><h2 id="临时绕过-给遇到同样问题的用户" tabindex="-1">临时绕过(给遇到同样问题的用户) <a class="header-anchor" href="#临时绕过-给遇到同样问题的用户" aria-label="Permalink to &quot;临时绕过(给遇到同样问题的用户)&quot;">​</a></h2><p>如果不想等修复,<strong>退出 ccswitch 进程</strong> 或把 <code>settings.json</code> 里 <code>&quot;visibleApps&quot;: { &quot;&amp;lt;agent&amp;gt;&quot;: false }</code> 设为 false 可以彻底规避 —— 但代价是 ccswitch 不能再帮你管理 <code>&amp;lt;agent&amp;gt;</code> 供应商。</p><p>也可以<strong>把 <code>&amp;lt;agent&amp;gt;</code> 的 <code>config.yaml</code> 重命名成 <code>config.yaml.bak</code></strong>(让原位置空)—— 这时 ccswitch 会自己创建一个小文件,在它上面&quot;切换&quot;是 in-place 编辑、不重复 —— 但<strong>这个文件只包含 ccswitch 关心的字段,<code>&amp;lt;agent&amp;gt;</code> 的所有个性化设置会丢</strong>。</p><h2 id="给其他用户的自查清单" tabindex="-1">给其他用户的自查清单 <a class="header-anchor" href="#给其他用户的自查清单" aria-label="Permalink to &quot;给其他用户的自查清单&quot;">​</a></h2><p>如果你也遇到类似 duplicate 报错,可以按下面顺序自查:</p><ol><li>看 <code>~/.cc-switch/logs/cc-switch.log</code> 最近 50 行,搜 <code>Failed to update &amp;lt;agent&amp;gt;</code> —— 有日志就是中招</li><li>看 <code>~/.cc-switch/backups/&amp;lt;app_type&amp;gt;/</code> 是否有最近 24 小时内的时间戳备份 —— 有就说明 ccswitch 在写</li><li>打开 <code>config.yaml</code> 找 <code>model:</code> / <code>custom_providers:</code> / <code>mcp_servers:</code> 这几个键是不是出现两次</li><li>临时绕过:退出 ccswitch 进程,问题立刻消失</li></ol>',34)])])}const m=e(d,[["render",i]]);export{u as __pageData,m as default};
